<?php require_once 'config.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM orders WHERE id=?');$s->execute([$id]);$o=$s->fetch();if(!$o){header('Location:index.php');exit;}$s=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$s->execute([$id]);$items=$s->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Order #<?=$o['id']?></title><link rel="stylesheet" href="style.css"><style>.receipt{max-width:650px;margin:50px auto;background:#fffaf3;padding:30px;border-radius:12px}.receipt table{width:100%;border-collapse:collapse}.receipt td,.receipt th{padding:10px;border-bottom:1px solid #decbb7}.right{text-align:right}.btn{background:#28551e;color:#fff;padding:10px 15px;border:0;border-radius:7px;text-decoration:none}</style></head><body><main class="receipt"><h1>Thank you for your order!</h1><p>Order #<?=$o['id']?> · <?=h($o['status'])?></p><p><?=h($o['customer_name'])?> · <?=h($o['customer_email'])?></p><table><tr><th>Item</th><th>Qty</th><th class="right">Subtotal</th></tr><?php foreach($items as $i):?><tr><td><?=h($i['product_name'])?></td><td><?=$i['quantity']?></td><td class="right">₱<?=number_format($i['subtotal'],2)?></td></tr><?php endforeach;?></table><h2 class="right">₱<?=number_format($o['total'],2)?></h2><a class="btn" href="index.php">Back to Shop</a> <button class="btn" onclick="print()">Print</button></main></body></html>
